<body>
    <div id="main-container"></div>

    <script>
        function init() {
            try {
                var emotionRaw = `$1`;
                var textRaw = `$2`;

                // 伊莉丝头像URL
                var avatarUrl = 'https://zora404.dpdns.org/file/1783705304943_小魔王__2_.png';

                var emotion = emotionRaw.trim();
                if (!emotion || emotion === '$1') {
                    emotion = '挑衅';
                }

                var text = textRaw.trim();
                if (!text || text === '$2') {
                    return;
                }

                // 安全的emotion类名
                var safeEmotion = emotion.replace(/[^a-zA-Z0-9_\-\u4e00-\u9fa5]/g, '');

                // 判断是否需要额外的wrapper类
                var wrapperClass = '';
                if (emotion === '愤怒') {
                    wrapperClass = ' angry';
                } else if (emotion === '沉默') {
                    wrapperClass = ' silent';
                }

                var html =
                    '<div class="iris-wrapper' + wrapperClass + '">' +
                    '    <div class="iris-avatar" id="iris-avatar-container">' +
                    '        <img src="' + avatarUrl + '" alt="伊莉丝" loading="lazy" ' +
                    '             onerror="document.getElementById(\'iris-avatar-container\').classList.add(\'img-error\');" ' +
                    '             onload="this.classList.add(\'img-loaded\');">' +
                    '    </div>' +
                    '    <div class="iris-dialogue-box">' +
                    '        <div class="iris-header">' +
                    '            <span class="iris-name">小魔王·伊莉丝</span>' +
                    '            <span class="iris-emotion emotion-' + safeEmotion + '">' + emotion + '</span>' +
                    '        </div>' +
                    '        <div class="iris-content">' + text + '</div>' +
                    '    </div>' +
                    '</div>';

                document.getElementById('main-container').innerHTML = html;

            } catch (error) {
                console.error("渲染错误:", error);
            }
        }

        init();
    </script>
</body>
